// ---- waterkeys ---------------------------------------------------------------------------------
const track3 = (() => {
  const COMP = {"0":[[0,0.5,3.8]],"1":[[0,0.55,1.9],[2,0.45,1.9]],"2":[[0,0.6,1.4],[1.5,0.5,0.5],[2,0.55,1.9]],"3":[[0,0.6,1.4],[1.5,0.5,0.5],[2,0.55,1.9]]}
const compAt = x => {
  const e = energy(x)
  if (e < 0 || role(x) === 'end') return null
  let h = null
  for (const c of COMP[e] ?? COMP[1]) if (c[0] <= mod(x, 4)) h = c
  return h && { at: floor(x / 4) * 4 + h[0], vel: h[1], d: h[2] }
}
  return {
  color: '#e6ccb2',
  graph: x => { const h = compAt(x), c = chordAt(x); return h && c && x - h.at < 0.35 ? c[3].map(n => -1 + (n - 48) / 20) : null },
  midi: x => { const h = compAt(x), c = chordAt(x); return h && c && x - h.at < Math.min(0.9, h.d * 0.9) ? c[3] : [] },
  formula: ["K = \\Rev\\sum_{j} P\\big(f_j,\\ t - j\\,\\Delta,\\ v_j\\big)\\ \\text{— аккорд берётся с лёгким арпеджиато, каждая нота на своём месте клавиатуры}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = polyWide(feltTone, { release: 0.6, life: 6, width: 0.6 }), fire = trigger(), verb = hall({ size: 1.25, decay: 3.6, damp: 4600, wet: 0.3 })
    return x => {
      const h = compAt(x), c = chordAt(x)
      if (h && c && fire(h.at)) {
        const v = 0.68 * h.vel
        c[3].forEach((n, j) => p.hit(hz(n - 60, C4), v * (0.86 + 0.14 * hash(h.at * 7 + j, 11)) * (j === c[3].length - 1 ? 1.08 : 1), h.d * sec + 0.6, j * 0.06))
        if (mod(h.at, 4) === 0) p.hit(hz(c[2] + 12 - 60, C4), 0.8 * v, h.d * sec + 0.6)
      }
      const [l, r] = p(), k = 1.9
      return verb(...[k * l, k * r])
    }
  },
}})()

