const track4 = {
  color: '#d0bfff',
  graph: x => (padOn(x) ? chordAt(x)[3].map(n => -1.7 + (n - 48) / 30) : null),
  midi: x => (padOn(x) && mod(x, 4) < 3.9 ? chordAt(x)[3] : []),
  formula: ["Pd = \\Rev\\sum_{j}\\sum_{i=1}^{N} a_i\\,W_{d}\\big(f_j\\,2^{(\\delta_i + v_i(t))/1200}\\big),\\quad W_d = \\sum_k \\frac{B(kf)}{k^{p(d)}}\\sin(2\\pi kft + \\varphi_k)\\ \\text{— N исполнителей на каждой ноте, каждый на несколько центов в стороне, со своим вибрато и местом в зале}"],
  audio() {
    const S = [section('ooh', { players: 5, centre: -0.15, spread: 0.8, vib: 1, seed: 20 }), section('mm', { players: 3, centre: 0.25, spread: 0.8, vib: 1, seed: 21 })], NONE = [], verb = hall({ size: 1.45, decay: 6, damp: 3600, pre: 0.035, wet: 0.36 })
    let F = S.map(() => NONE), last = null
    return x => {
      const on = padOn(x), c = on ? chordAt(x) : null
      if (c && c !== last) { last = c; F = [c[3].map(n => hz(n + 0 - 60, C4)), c[3].map(n => hz(n + -12 - 60, C4))] }
      const lv = [0.3,0.45,0.62,0.85][Math.max(0, energy(x))] ?? 0.4
      let l = 0, r = 0
      { const [a, b] = S[0](on ? F[0] : NONE, lv); l += 1 * a; r += 1 * b }
      { const [a, b] = S[1](on ? F[1] : NONE, lv); l += 0.45 * a; r += 0.45 * b }
      const k = 0.5 * (0.7 + 0.5 * lv)
      return verb(...[k * l, k * r])
    }
  },
}

// ---- bass --------------------------------------------------------------------------------------
const track5 = (() => {
  const BASS_LINE = [[0,"R",3.5]]
const bassAt = x => {
  const c = chordAt(x), e = energy(x)
  if (!c || e < 1 || x >= END - 1) return null
  const p = mod(x, 4), bar = floor(x / 4) * 4
  let hit = null
  for (const h of BASS_LINE) if (h[0] <= p && p < h[0] + h[2]) hit = h
  if (!hit) return null
  const next = chordAt(bar + 4) ?? c, [third, fifth] = c[5]
  const n = hit[1] === 'R' ? c[2] : hit[1] === '5' ? c[2] + fifth : hit[1] === '8' ? c[2] + 12 : hit[1] === '3' ? c[2] + third : next[2] - 1
  return { n, at: bar + hit[0], d: hit[2] }
}
  return {
  color: '#4d7cff',
  graph: x => (bassAt(x) ? -3 + (bassAt(x).n - 28) / 24 : null),
  midi: x => (bassAt(x) && x - bassAt(x).at < bassAt(x).d * 0.9 ? [bassAt(x).n] : []),
  formula: ["Sb = \\tanh\\!\\big(1.6\\,a\\,(\\sin\\varphi + 0.12\\sin 2\\varphi)\\big),\\quad \\varphi = 2\\pi\\!\\int\\! f,\\ f \\text{ — скользит к новой ноте 25 мс}"],
  audio({ bpm }) {
    const o1 = osc('sine'), o2 = osc('sine'), glide = smooth(25), env = smooth(9)
    let n = 36
    return x => {
      const m = bassAt(x), on = m && x - m.at < m.d * 0.9
      if (m) n = m.n
      const f = hz(glide(n) - 60, C4), a = env(on ? 1 : 0)
      return 0.3472 * tanh(1.6 * a * (o1(f) + 0.12 * o2(2 * f))) / 0.9217
    }
  },
}})()

